window.docContents[101].resolve({"/releases/#docstring-labeled-groups":{"contents":"They were headings, which placed them in the document's heading outline even though they name parts of a declaration rather than sections of the text. Each label is now a paragraph tied by aria-labelledby to a container with role=\"group\", so heading navigation reaches the document's own structure.\n\n\n","context":"Writing Documentation in Lean with Verso\u0009Release Notes\u0009Verso 4.32.0","header":"Labeled Groups in Rendered Docstrings","id":"/releases/#docstring-labeled-groups"}});